import{_ as l,C as s,o as i,c as n,j as a,a as o,E as t,a2 as d}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Livrer","description":"","frontmatter":{"title":"Livrer"},"headers":[],"relativePath":"agent/livrer.md","filePath":"agent/livrer.md"}'),c={name:"agent/livrer.md"};function u(p,e,v,f,m,g){const r=s("Ask");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"livrer",tabindex:"-1"},[o("Livrer "),a("a",{class:"header-anchor",href:"#livrer","aria-label":'Permalink to "Livrer"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Ce parcours sert à livrer une nouvelle version, du projet entier ou d'un seul module, puis à la publier sur le canal public. Vous y venez quand une version est prête et que vous voulez que l'agent déroule la livraison à votre place.",-1)),e[2]||(e[2]=a("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[o("Ce que vous demandez à l'agent "),a("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(r,{say:"Prépare la livraison du module site en patch et montre-moi le plan.",verb:"effortless_release_plan",family:"livraison",args:'{"bump":"patch","stack":"site"}'}),t(r,{say:"Quel serait le tag si on livrait le projet entier en mineur ?",verb:"effortless_release_plan",family:"livraison",args:'{"bump":"minor"}'}),t(r,{say:"Configure la livraison du module site : build avec pnpm build, artefacts dans dist/*.zip.",verb:"effortless_release_delivery_set",family:"livraison",args:'{"stack":"site","build_command":"pnpm build","artifacts":"dist/*.zip"}'}),t(r,{say:"Active le tag et la mise à jour de la documentation dans la configuration de release.",verb:"effortless_release_config_set",family:"livraison",args:'{"tag":true,"update_docs":true}'}),t(r,{say:"Déclare acme/site-dev comme dépôt interne et acme/site comme dépôt public pour le module site.",verb:"effortless_release_channels_set",family:"livraison",args:'{"stack":"site","internal":"acme/site-dev","public":"acme/site"}'}),t(r,{say:"Livre le module site : incrémente la version, commit et push, tag, build et artefacts.",verb:"effortless_release_apply",family:"livraison",args:'{"steps":"bump_version,git_flow,tag_release,delivery","stack":"site"}'}),e[3]||(e[3]=a("p",null,[a("em",null,"(l'agent vous demande votre accord avant)")],-1)),t(r,{say:"Publie en public la version site-v1.4.1 déjà livrée en interne.",verb:"effortless_release_promote",family:"livraison",args:'{"stack":"site","tag":"site-v1.4.1","confirm":"site-v1.4.1"}'}),e[4]||(e[4]=a("p",null,[a("em",null,"(l'agent vous demande votre accord avant)")],-1)),t(r,{say:"Montre-moi l'historique des livraisons.",verb:"effortless_deliveries",family:"livraison"}),t(r,{say:"Où en est la livraison de la 0.2.47 ? Plateformes, CI, public.",verb:"effortless_release_track",family:"livraison",args:'{"tag":"v0.2.47"}'}),t(r,{say:"Retire la v0.2.46 du canal public.",verb:"effortless_release_public_retire",family:"livraison",args:'{"tag":"v0.2.46","confirm":"v0.2.46"}'}),e[5]||(e[5]=a("p",null,[a("em",null,"(l'agent vous demande votre accord avant)")],-1)),t(r,{say:"Ouvre la livraison de la 0.2.47 avant de toucher aux numéros de version.",verb:"effortless_release_open",family:"livraison",args:'{"version":"0.2.47"}'}),t(r,{say:"La 0.2.47 est livrée : ferme la livraison.",verb:"effortless_release_close",family:"livraison",args:'{"status":"done"}'}),t(r,{say:"Qu'est-ce qui part dans cette livraison ? Rédige-moi un brouillon de notes en français et en anglais.",verb:"effortless_release_content",family:"livraison"}),t(r,{say:"Les notes me vont : enregistre-les pour la livraison.",verb:"effortless_release_notes_set",family:"livraison",args:'{"notes":"…"}'}),e[6]||(e[6]=d('<p><em>(l&#39;agent vous montre le brouillon et attend votre accord)</em></p><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="planifier-une-livraison" tabindex="-1">Planifier une livraison <a class="header-anchor" href="#planifier-une-livraison" aria-label="Permalink to &quot;Planifier une livraison&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-plan"><code>effortless_release_plan</code></a> calcule le plan sans rien écrire : version courante et version cible, tag, dépôt, branche, fichiers de version. <code>bump</code> vaut <code>patch</code> (défaut), <code>minor</code> ou <code>major</code>. <code>stack</code> vise un module ; sans <code>stack</code>, le plan porte sur le projet entier.</li><li>Le tag dépend de la cible : <code>vX.Y.Z</code> pour le projet entier ou pour un module qui a son propre dépôt, <code>&lt;module&gt;-vX.Y.Z</code> pour un module qui vit dans le dépôt du projet.</li></ol><h3 id="configurer-la-livraison" tabindex="-1">Configurer la livraison <a class="header-anchor" href="#configurer-la-livraison" aria-label="Permalink to &quot;Configurer la livraison&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-config-show"><code>effortless_release_config_show</code></a> lit la configuration de release effective.</li><li><a href="/Effortless/reference/mcp/livraison.html#release-config-set"><code>effortless_release_config_set</code></a> règle trois options : <code>git_flow</code> (étape de commit et de push), <code>tag</code> (création du tag) et <code>update_docs</code> (mise à jour de la documentation). Il en faut au moins une.</li><li><a href="/Effortless/reference/mcp/livraison.html#release-delivery-set"><code>effortless_release_delivery_set</code></a> enregistre, pour un module (ou <code>default</code>), la commande de build (<code>build_command</code>) et les artefacts à envoyer (<code>artifacts</code>, en globs séparés par des virgules). Sans <code>artifacts</code>, ceux déjà enregistrés sont conservés. Un module non déclaré est refusé.</li></ol><h3 id="ouvrir-et-fermer-une-livraison" tabindex="-1">Ouvrir et fermer une livraison <a class="header-anchor" href="#ouvrir-et-fermer-une-livraison" aria-label="Permalink to &quot;Ouvrir et fermer une livraison&quot;">​</a></h3><p>Le hook anti-dérive refuse un commit de code sans tâche en cours. Une livraison ouverte porte ses propres commits (numéros de version, notes, correctif de dernière minute) sans détourner une tâche.</p><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-open"><code>effortless_release_open</code></a> ouvre la livraison <code>REL-&lt;version&gt;</code> (ou <code>REL-&lt;module&gt;-&lt;version&gt;</code> avec <code>stack</code>). Sans <code>version</code>, il prend la cible du plan. Une seule livraison peut être ouverte à la fois.</li><li>Tant qu&#39;elle est ouverte, le hook accepte les commits et nomme la livraison qui les porte.</li><li><a href="/Effortless/reference/mcp/livraison.html#release-close"><code>effortless_release_close</code></a> la ferme : <code>done</code> (livrée, par défaut) ou <code>stopped</code> (abandonnée). Le hook exige de nouveau une tâche en cours.</li><li><code>effortless_release_apply</code> réutilise une livraison ouverte pour la même cible. S&#39;il n&#39;y en a pas, il ouvre la sienne et la ferme à la fin, <code>stopped</code> si une étape échoue.</li><li>Une livraison ouverte depuis plus de 24 h apparaît dans « Ce qui t&#39;attend ».</li></ol><h3 id="calculer-le-contenu-et-rediger-les-notes" tabindex="-1">Calculer le contenu et rédiger les notes <a class="header-anchor" href="#calculer-le-contenu-et-rediger-les-notes" aria-label="Permalink to &quot;Calculer le contenu et rédiger les notes&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-content"><code>effortless_release_content</code></a> calcule ce que contient la livraison depuis le dernier tag de la cible, sans rien écrire : les épics et stories cités par les commits, les évolutions résolues depuis (<code>new</code> pour les fonctionnalités et améliorations, <code>fixed</code> pour les anomalies), et les commits sans référence, nommés à part. Une évolution résolue le jour même du tag est rangée dans <code>sameDay</code> : elle a pu partir dans la livraison précédente, l&#39;agent vous la signale. Pour un module, seuls les commits de son dossier comptent.</li><li>L&#39;agent en tire un brouillon de notes en français puis en anglais, vous le montre, et attend votre accord.</li><li><a href="/Effortless/reference/mcp/livraison.html#release-notes-set"><code>effortless_release_notes_set</code></a> enregistre les notes validées de la livraison ouverte dans <code>&lt;notes_dir&gt;/&lt;version&gt;.md</code>. Le dossier se règle par <code>effortless_release_config_set</code> (<code>notes_dir</code>, défaut <code>.effortless/notes</code>).</li><li>L&#39;étape « Tag et release GitHub » publie ces notes à la place des notes générées par GitHub.</li></ol><h3 id="executer-la-livraison" tabindex="-1">Exécuter la livraison <a class="header-anchor" href="#executer-la-livraison" aria-label="Permalink to &quot;Exécuter la livraison&quot;">​</a></h3><p>Cette étape agit pour de vrai : écriture des fichiers de version, commit, push, tag, release GitHub, build. L&#39;agent ne l&#39;exécute <strong>qu&#39;après votre accord explicite</strong>.</p><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-apply"><code>effortless_release_apply</code></a> reçoit <code>steps</code> (parmi <code>bump_version</code>, <code>git_flow</code>, <code>tag_release</code>, <code>update_docs</code>, <code>delivery</code>), <code>bump</code> et, pour un module, <code>stack</code>.</li><li>Les étapes se jouent toujours dans cet ordre. Une étape en échec arrête la chaîne : les suivantes sont rapportées « non jouée ». Une étape que le moteur ne peut pas faire (par exemple sans <code>gh</code>) est rapportée « à faire à la main », avec ce qu&#39;il reste à faire.</li><li><strong>Incrémenter la version</strong> vérifie tous les fichiers de version avant d&#39;en écrire un seul. <strong>Commit et push</strong> ne fusionne sur la branche principale que par avance rapide. <strong>Tag et release GitHub</strong> refuse de poser un tag sur des fichiers non commités : le tag désignerait le commit d&#39;avant, sans la nouvelle version.</li><li>L&#39;agent relit le résultat étape par étape et vous le résume.</li></ol><h3 id="declarer-les-canaux-interne-et-public" tabindex="-1">Déclarer les canaux interne et public <a class="header-anchor" href="#declarer-les-canaux-interne-et-public" aria-label="Permalink to &quot;Déclarer les canaux interne et public&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-channels-set"><code>effortless_release_channels_set</code></a> règle les deux dépôts de release d&#39;une cible (<code>stack</code>, ou <code>default</code> pour le projet entier) : <code>internal</code> (vide = le dépôt d&#39;origine) et <code>public</code> (vide = pas de canal public). Un paramètre absent reste inchangé. Un dépôt s&#39;écrit <code>owner/nom</code>.</li></ol><h3 id="publier-en-public" tabindex="-1">Publier en public <a class="header-anchor" href="#publier-en-public" aria-label="Permalink to &quot;Publier en public&quot;">​</a></h3><p>La publication publique <strong>promeut</strong> une version déjà livrée en interne, sans la reconstruire : même tag, aucun nouveau bump. Seuls les fichiers de l&#39;édition publique sortent (ceux d&#39;une édition <code>pro</code> restent en interne, la réponse les nomme dans <code>withheld</code>) ; le flux de mise à jour reçoit les adresses de téléchargement publiques ; les notes sont celles de <code>&lt;notes_dir&gt;/&lt;version&gt;.md</code>. Un flux qui désigne un fichier retenu est refusé (<code>release:privateInPublic</code>) : rien ne sort. Elle est irréversible. L&#39;agent ne la lance <strong>qu&#39;après votre accord explicite</strong>.</p><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-promote"><code>effortless_release_promote</code></a> reçoit <code>tag</code> (le tag déjà livré en interne), <code>stack</code> pour un module, et <code>confirm</code>, qui doit redonner exactement le même tag.</li><li>Le moteur télécharge la release interne, la republie sur le dépôt public et inscrit la publication au journal.</li></ol><h3 id="suivre-la-livraison-et-retirer-les-anciennes-publiques" tabindex="-1">Suivre la livraison et retirer les anciennes publiques <a class="header-anchor" href="#suivre-la-livraison-et-retirer-les-anciennes-publiques" aria-label="Permalink to &quot;Suivre la livraison et retirer les anciennes publiques&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#release-track"><code>effortless_release_track</code></a> calcule l&#39;état réel de la livraison d&#39;un tag depuis GitHub, quel que soit le chemin suivi (agent, scripts, à la main) : la release sur le canal interne et sur le canal public (présente, marquée <code>latest</code>, fichiers), les plateformes servies par chaque feed <code>latest*.json</code> et celles qui manquent si le projet les déclare dans <code>release-platforms.json</code>, les runs de CI du tag, et les anciennes releases publiques encore en place. Sans <code>tag</code>, il suit la livraison ouverte, sinon la plus récente. Il garde le résultat dans le journal.</li><li><a href="/Effortless/reference/mcp/livraison.html#release-public-retire"><code>effortless_release_public_retire</code></a> retire une ancienne release publique et son tag. C&#39;est irréversible : l&#39;agent ne le fait <strong>qu&#39;après votre accord explicite</strong>, et <code>confirm</code> doit redonner exactement le tag. La release <code>latest</code> du public ne se retire pas.</li></ol><h3 id="relire-l-historique" tabindex="-1">Relire l&#39;historique <a class="header-anchor" href="#relire-l-historique" aria-label="Permalink to &quot;Relire l&#39;historique&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/livraison.html#deliveries"><code>effortless_deliveries</code></a> rend le journal des livraisons, la plus récente d&#39;abord : date, canal, module, tag, version, dépôt, issue. Il rend aussi les canaux de chaque cible. Il ne demande pas de réseau.</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Les fichiers de version à la nouvelle valeur, un commit, un tag annoté et, si le dépôt est sur GitHub et que <code>gh</code> est disponible, une release avec ses artefacts.</li><li>Chaque livraison, réussie ou arrêtée, et chaque publication, s&#39;inscrit dans <code>.effortless/deliveries.json</code>, versionné avec le projet.</li><li>Dans l&#39;app, l&#39;écran <a href="/Effortless/guide/release.html">Livraison</a> montre le même plan, la même configuration, les canaux et l&#39;<strong>Historique des livraisons</strong>.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Le projet est en mode semi-auto</td><td><code>release_apply</code> rend un message « outil d&#39;exécution désactivé » (marqué <code>gated</code>) ; <code>release_promote</code> est refusé avec <code>release:gated</code></td><td>Passer le projet en mode full, puis redemander la livraison.</td></tr><tr><td>Le module n&#39;existe pas</td><td><code>release:unknownModule</code> (plan, exécution, canaux) ; <code>deploiement:stackUnknown</code> pour la configuration de livraison</td><td>Passer l&#39;identifiant d&#39;un module déclaré, ou <code>default</code> / aucun <code>stack</code> pour le projet entier.</td></tr><tr><td>Aucune étape sélectionnée</td><td><code>deploiement:noStepSelected</code></td><td>Choisir au moins une étape valide dans <code>steps</code> (les identifiants inconnus sont ignorés).</td></tr><tr><td>Une étape échoue pendant l&#39;exécution</td><td><code>deploiement:applyStopped</code>, avec le détail de l&#39;étape en échec</td><td>Corriger la cause nommée dans le détail, puis relancer. Les étapes déjà faites ne sont pas annulées.</td></tr><tr><td>Tag demandé alors que des fichiers ne sont pas commités</td><td>Étape <code>tag_release</code> en échec : « Tag … non posé »</td><td>Rejouer avec l&#39;étape <code>git_flow</code>, ou commiter d&#39;abord.</td></tr><tr><td><code>release_config_set</code> sans aucune option</td><td><code>deploiement:configNoField</code></td><td>Passer au moins <code>git_flow</code>, <code>tag</code> ou <code>update_docs</code>.</td></tr><tr><td>Livraison sans module précisé</td><td><code>deploiement:stackRequired</code></td><td>Passer <code>stack</code> ; <code>effortless_stack_list</code> nomme celles déclarées.</td></tr><tr><td>Dépôt mal écrit</td><td><code>release:repoInvalid</code></td><td>Écrire le dépôt <code>owner/nom</code>, ou une valeur vide pour retirer le canal.</td></tr><tr><td>Aucun dépôt public déclaré</td><td><code>release:noPublicChannel</code></td><td>Le déclarer avec <code>effortless_release_channels_set</code>.</td></tr><tr><td><code>confirm</code> différent du tag</td><td><code>release:confirmMismatch</code></td><td>Redonner exactement le tag, après votre accord explicite.</td></tr><tr><td>La version n&#39;a pas été livrée en interne</td><td><code>release:notInternal</code></td><td>Livrer d&#39;abord la version en interne (étape « Tag et release GitHub »).</td></tr><tr><td>La version est déjà publique</td><td><code>release:alreadyPublic</code></td><td>Rien à faire. Pour une nouvelle version, la livrer d&#39;abord en interne.</td></tr><tr><td><code>gh</code> absent ou en échec pendant une publication</td><td><code>release:ghMissing</code> ou <code>release:ghFailed</code></td><td>Installer <code>gh</code> et vous y connecter, puis rejouer.</td></tr><tr><td>Une livraison est déjà ouverte</td><td><code>release:deliveryAlreadyOpen</code></td><td>La fermer par <code>effortless_release_close</code>, puis rouvrir.</td></tr><tr><td>Aucune livraison ouverte à fermer</td><td><code>release:noOpenDelivery</code></td><td>En ouvrir une par <code>effortless_release_open</code>.</td></tr><tr><td>Version mal écrite à l&#39;ouverture</td><td><code>release:invalidVersion</code></td><td>Écrire la version <code>1.2.3</code>, ou l&#39;omettre pour prendre la cible du plan.</td></tr><tr><td>Le tag de la version existe déjà</td><td><code>release:tagExists</code></td><td>Choisir une autre version : celle-ci est déjà livrée.</td></tr><tr><td><code>release_apply</code> alors qu&#39;une livraison est ouverte pour une autre cible</td><td><code>release:deliveryMismatch</code></td><td>Fermer la livraison ouverte, ou viser sa version et son module.</td></tr><tr><td>Notes enregistrées sans livraison ouverte</td><td><code>release:noOpenDelivery</code></td><td>Ouvrir la livraison par <code>effortless_release_open</code>, puis enregistrer les notes.</td></tr><tr><td>Notes vides</td><td><code>release:notesEmpty</code></td><td>Passer le texte validé dans <code>notes</code>.</td></tr><tr><td>Aucune livraison à suivre</td><td><code>release:noDelivery</code></td><td>Passer le tag dans <code>tag</code>, ou ouvrir une livraison.</td></tr><tr><td>La release à retirer n&#39;est pas publique</td><td><code>release:notPublic</code></td><td>Rien à retirer ; <code>effortless_release_track</code> liste les anciennes publiques.</td></tr><tr><td>La release à retirer est la <code>latest</code> publique</td><td><code>release:retireLatest</code></td><td>Publier d&#39;abord une version plus récente, puis retirer celle-ci.</td></tr></tbody></table>',27))])}const _=l(c,[["render",u]]);export{b as __pageData,_ as default};
